-- Aggiunge specie.lingua_descrizione e la popola con un rilevatore di lingua
-- locale (rapporto di function word IT vs EN, script
-- scripts/rileva-lingua-descrizione.py). Punto 6 del piano di naturalizzazione
-- (issue #153): sostituisce lo scoping SQL fragile a regex (descrizione ~*
-- '\mthe\M' / '\mis a\M', ~4% di falsi negativi) con un attributo interrogabile
-- e rigenerabile.
--
-- Valori: it | en | mixed | stub | nd
--   it     testo in italiano
--   en     prosa PFAF/RHS in inglese non tradotta
--   mixed  prosa italiana con blocchi inglesi non tradotti
--   stub   solo prefisso label / poche parole, nessun testo descrittivo reale
--   nd     segnale troppo debole per decidere
--
-- Popolata solo per le righe madri (specie_padre_id is null) con descrizione
-- non vuota: 15.649 righe. Il blocco RHS marcato resta scopato dalla stringa
-- letterale 'testo originale in inglese' (zero falsi negativi); lingua_descrizione
-- serve soprattutto per l'inglese NON marcato -> oggi:
--   select slug from specie
--   where lingua_descrizione = 'en'
--     and descrizione not ilike '%testo originale in inglese%';   -- ~100 righe

alter table public.specie
  add column if not exists lingua_descrizione text
  check (lingua_descrizione in ('it','en','mixed','stub','nd'));

comment on column public.specie.lingua_descrizione is
  'Lingua della descrizione (it|en|mixed|stub|nd), da scripts/rileva-lingua-descrizione.py. '
  'Rigenerabile. Usata dallo scoping delle fasi di naturalizzazione al posto delle regex.';

